      "Product catalogs": "ప్రొడక్ట్ కేటలాగ్‌లు",
      "Showcase products and help customers shop inside WhatsApp.": "WhatsApp లో ఉత్పత్తులను ప్రదర్శించండి మరియు కస్టమర్‌లు షాపింగ్ చేయడానికి సహాయపడండి.",
      "Onboard": "ఆన్‌బోర్డ్",
      "Get help setting up your WhatsApp Business API and verification.": "మీ WhatsApp Business API మరియు వెరిఫికేషన్‌ను సెటప్ చేయడంలో సహాయం పొందండి.",
      "Connect": "కనెక్ట్",
