      "Turn common questions and customer journeys into repeatable experiences.": "பொதுவான கேள்விகள் மற்றும் வாடிக்கையாளர் பயணங்களை மீண்டும் மீண்டும் செய்யக்கூடிய அனுபவங்களாக மாற்றவும்.",
      "Support people when they need you and learn from every interaction.": "மக்களுக்குத் தேவைப்படும்போது அவர்களுக்கு ஆதரவளியுங்கள் மற்றும் ஒவ்வொரு தொடர்பிலிருந்தும் கற்றுக்கொள்ளுங்கள்.",
      "WhatsApp Business API onboarding": "WhatsApp Business API ஆன்போர்டிங்",
      "Get guided setup for Meta verification and Green Tick assistance.": "Meta சரிபார்ப்பு மற்றும் கிரீன் டிக் உதவிக்கு வழிகாட்டப்பட்ட அமைப்பைப் பெறுங்கள்.",
      "Message templates": "செய்தி வார்ப்புருக்கள்",
