      "Chatbot builder": "சாட்பாட் பில்டர்",
      "Automate FAQs, capture leads, and share order status.": "FAQs தானியக்கமாக்குங்கள், லீட்களைப் பெறுங்கள் மற்றும் ஆர்டர் நிலையைப் பகிருங்கள்.",
      "WhatsApp Flows": "WhatsApp Flows",
      "Create in-chat forms for bookings, applications, and surveys.": "புக்கிங், விண்ணப்பங்கள் மற்றும் கருத்துக்கணிப்புகளுக்கு இன்-சாட் படிவங்களை உருவாக்குங்கள்.",
      "Website integration": "இணையதள ஒருங்கிணைப்பு",
