      "Connect": "இணைக்கவும்",
      "Bring your website, CRM, or existing software into the workflow.": "உங்கள் இணையதளம், CRM அல்லது ஏற்கனவே உள்ள மென்பொருளை உங்கள் பணிப்பாய்வுக்குக் கொண்டு வாருங்கள்.",
      "Automate": "தானியக்கமாக்கு",
      "Set up templates, chatbots, flows, and campaigns for your team.": "உங்கள் குழுவிற்கான டெம்ப்ளேட்டுகள், சாட்பாட்கள், ஓட்டங்கள் மற்றும் பிரச்சாரங்களை அமைக்கவும்.",
