      "answers.setup": "atWassup એક અધિકૃત Meta બિઝનેસ પાર્ટનર છે. અમારી ટીમ તમને WhatsApp Business API સેટઅપ અને Meta વેરિફિકેશનમાં માર્ગદર્શન આપી શકે છે; Meta અંતિમ મંજૂરીનો નિર્ણય લે છે.",
      "answers.integrations": "atWassup તમારા CRM અને હાલના સાધનો સાથે કનેક્ટ થઈ શકે છે. તમારા વર્તમાન સેટઅપ માટે શું યોગ્ય છે, તે અમારી ટીમ જણાવી શકે છે.",
      "answers.capture": "જ્યારે કોઈ ગ્રાહક પહેલીવાર તમારા કનેક્ટેડ WhatsApp Business નંબર પર મેસેજ કરે છે, ત્યારે atWassup તેમનો નંબર સેવ કરે છે. માર્કેટિંગ માટે, તેઓ શેર કરેલી અથવા તમારા ચેટબોટ દ્વારા પૂછવામાં આવેલી વિગતો જેવી કે નામ, પિનકોડ, સરનામું અથવા કસ્ટમ માહિતી પણ સેવ કરી શકે છે.",
