      "answers.features": "atWassup WhatsApp Business API ಆನ್‌ಬೋರ್ಡಿಂಗ್, AI ಅಸಿಸ್ಟೆಂಟ್‌ಗಳು ಮತ್ತು ಏಜೆಂಟ್‌ಗಳು, ಚಾಟ್‌ಬಾಟ್‌ಗಳು, ಫಾಲೋ-ಅಪ್‌ಗಳು, ಬ್ರಾಡ್‌ಕಾಸ್ಟ್‌ಗಳು, ಫಾರ್ಮ್‌ಗಳು, ಕ್ಯಾಟಲಾಗ್‌ಗಳು, ಪಾವತಿಗಳು ಮತ್ತು ಅನಲಿಟಿಕ್ಸ್‌ಗಳನ್ನು ಒಂದೇ ಕಡೆ ತರುತ್ತದೆ.",
      "answers.setup": "atWassup ಒಂದು ಅಧಿಕೃತ Meta ಬಿಸಿನೆಸ್ ಪಾರ್ಟ್ನರ್ ಆಗಿದೆ. ನಮ್ಮ ತಂಡವು ನಿಮ್ಮ WhatsApp Business API ಸೆಟಪ್ ಮತ್ತು Meta ಪರಿಶೀಲನೆಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಬಲ್ಲದು; ಅಂತಿಮ ಅನುಮೋದನೆಯ ನಿರ್ಧಾರವನ್ನು Meta ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ.",
      "answers.integrations": "atWassup ನಿಮ್ಮ CRM ಮತ್ತು ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಪರಿಕರಗಳೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸಬಹುದು. ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಸೆಟಪ್‌ಗೆ ಯಾವುದು ಸೂಕ್ತವೆಂದು ನಮ್ಮ ತಂಡವು ಖಚಿತಪಡಿಸಬಹುದು.",
