      "answers.team": "ನಾನು atWassup ತಂಡಕ್ಕೆ ಫಾಲೋ-ಅಪ್ ಮಾಡಲು ಹೇಳಬಲ್ಲೆ. ನಿಮ್ಮ ಸಂಪರ್ಕ ವಿವರಗಳನ್ನು ಮತ್ತು ನಿಮಗೆ ಯಾವ ವಿಷಯದಲ್ಲಿ ಸಹಾಯ ಬೇಕು ಎಂಬುದನ್ನು ತಿಳಿಸಿ.",
      "answers.fallback": "ಇದಕ್ಕೆ ನನ್ನ ಬಳಿ ಇನ್ನೂ ಪರಿಶೀಲಿಸಿದ ಉತ್ತರವಿಲ್ಲ. ನಿಮ್ಮ ಹೆಸರು, WhatsApp ಸಂಖ್ಯೆ ಮತ್ತು ಪ್ರಶ್ನೆಯನ್ನು ಹಂಚಿಕೊಳ್ಳಲು ಕೆಳಗಿನ ಸಂಪರ್ಕ ಆಯ್ಕೆಯನ್ನು ಬಳಸಿ, ಇದರಿಂದ atWassup ತಂಡವು ನಿಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು."
